import{_ as t,a,o as s,ai as o}from"./chunks/framework.BbOtTPsL.js";const h=JSON.parse('{"title":"Mass Update Invoice Status","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-invoices-mass-update-status-gql","title":"Mass Update Invoice Status","description":"Bulk-set the status of several invoices at once. A manual status override — it does not capture or reverse a payment.","query":"mutation MassUpdateInvoiceStatus($input: createAdminInvoiceMassUpdateStatusInput!) {\\n  createAdminInvoiceMassUpdateStatus(input: $input) {\\n    adminInvoiceMassUpdateStatus {\\n      updated\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"indices\\": [560, 561],\\n    \\"value\\": \\"paid\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminInvoiceMassUpdateStatus\\": {\\n      \\"adminInvoiceMassUpdateStatus\\": {\\n        \\"updated\\": [560, 561],\\n        \\"message\\": \\"Invoice status updated successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/invoices/mass-update-status.md","filePath":"api/graphql-api/admin/sales/invoices/mass-update-status.md","lastUpdated":1781099665000}'),n={name:"api/graphql-api/admin/sales/invoices/mass-update-status.md"};function d(i,e,r,c,p,u){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="mass-update-invoice-status" tabindex="-1">Mass Update Invoice Status <a class="header-anchor" href="#mass-update-invoice-status" aria-label="Permalink to &quot;Mass Update Invoice Status&quot;">​</a></h1><p>GraphQL counterpart of <code>POST /api/admin/invoices/mass-update-status</code>. Bulk-sets the status of a batch of invoices — the operation behind the admin Invoices datagrid&#39;s &quot;Update Status&quot; bulk action. Requires the <code>sales.invoices.view</code> permission. All admin endpoints require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p><div class="warning custom-block"><p class="custom-block-title">This is a manual status override</p><p>Setting an invoice to <code>paid</code> here <strong>does not capture a payment</strong>, and setting it to <code>pending</code> / <code>overdue</code> does <strong>not</strong> reverse one. It only changes the stored status flag.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminInvoiceMassUpdateStatus(input)</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>indices</code></td><td><code>[Int!]!</code></td><td>Ids of the invoices to update. Must be non-empty.</td></tr><tr><td><code>value</code></td><td><code>String!</code></td><td>New status — one of <code>pending</code>, <code>paid</code>, <code>overdue</code>.</td></tr></tbody></table><h2 id="payload" tabindex="-1">Payload <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;Payload&quot;">​</a></h2><p><code>message</code> is the field to read for confirmation. The <code>updated</code> ids are also returned; over GraphQL this list is wrapped in a paginated envelope, so the <strong>REST</strong> response is the canonical place to read the flat <code>updated</code> array. Empty <code>indices</code> or an out-of-range <code>value</code> returns an error in <code>errors[]</code>.</p>',9)]))}const m=t(n,[["render",d]]);export{h as __pageData,m as default};
